static void SceneMain(OMOBJ *object)
{
    switch (object->mode) {
        case 0:
            object->mode = 1;
            /* fallthrough */
        case 1:
            if (!omSysExitReq) {
                break;
            }
            object->mode = 2;
            /* fallthrough */
        case 2:
            WipeCreate(WIPE_MODE_OUT, WIPE_TYPE_NORMAL, 60);
            HuAudFadeOut(1000);
            object->mode = 3;
            /* fallthrough */
        case 3:
            if (WipeStatGet() == 0) {
                OptionStateKill(optionState);
                if (rumbleF != GWGameStat.rumble) {
                    omSysExitReq = 0;
                    KillScene();
                }
                omOvlReturnEx(1, 1);
            }
            break;
    }
}

